   92:     conv1d(wc, bc, cur, &uc, dim_s, nxt, 1, 1, 0, 1, Tn);
   93:     if (uc.d == NULL || uc.len != uc_need)
   94:       {
   95:         printf("[UP] 1x1 卷积暂存 %d floats 分配失败\n", uc_need);
   96:         dec_mem("upc 失败", -1, Tn);
   97:         if (uc_own) { t_free(&uc); }
   98:         up->d = NULL; up->len = 0; up->shape[2] = 0;
   99:         return -1;
  100:       }
  101: 
  102:     if (!last_stage)
  103:       {
  104:         /* 关键一步：cur 已经读干净了，放掉它让空闲大块合并回来 */
  105:         t_free(cur);
  106:         float *nd = (float*)jx_arealloc(up->d, (size_t)up->len * sizeof(float));
  107:         if (nd == NULL)
  108:           {
  109:             printf("[UP] 上采样输出 %d floats (%.2fMB) 分配失败\n",
  110:                    up->len, (double)up->len * 4.0 / 1.0e6);
  111:             dec_mem("up 大块失败", -1, Tn);
  112:             if (uc_own) { t_free(&uc); }
  113:             up->d = NULL; up->len = 0; up->shape[2] = 0;
  114:             return -1;
  115:           }
  116:         up->d = nd;
  117:       }
  118: 
  119:     upsampling_linear(&uc, up, B, nxt, Tn, scale);
  120:     if (uc_own) { t_free(&uc); }
  121:     if (up->len != B * nxt * Tout)
  122:       {
  123:         printf("[UP] up 张量不完整\n");
  124:         up->len = 0; return -1;
  125:       }
  126:     channel_norm_first(up, wn, bn, B, nxt, Tout);
  127:     return 0;
  128: }
  129: 
  130: /* ============================ 末段流式兜底（长录音） ============================ */
  131: /* 正常路径：decoder_up_path 先把整段 up [B,nxt,Tout] 物化出来（4 秒音频 4.10MB），
  132:  * 再在整段上跑 3 个 LegacyUnit + Snake + conv(k=7)。4 秒音频时 up(4.10MB) 与
  133:  * 上一 stage 的 cur [B,28,32016](3.59MB) 必须同时活着 = 7.7MB；板端 8.5MB PSRAM
  134:  * 堆里空闲有 4.84MB 但最大连续只有 2.54MB（cur 卡在中间把空闲劈成两半），
  135:  * realloc 拿不到 4MB -> 整段输出作废。3 秒已经能在这个堆里跑通，4 秒就差这一块。
  136:  *
  137:  * 这里把末段整个摊平：按输出块算一小段 up（复用 decoder_up_path 那套 1 样点
  138:  * halo 的分块，逐位一致），就地接着跑 Legacy/Snake/末层卷积，只把 [u0,u1)
  139:  * 写回 out，永不物化整段 [nxt,Tout] 与整段 [1,16,T]。峰值降到只剩上一 stage
  140:  * 的 cur + 几块百 KB 级工作缓冲（4 秒约 3.9MB）。
  141:  *
  142:  * halo：末段链是 up -> ChannelNorm -> [Snake->conv7(dil)]x3 -> Snake -> conv7(p=3)，
  143:  * 各段感受野半径 = 27(最后那个 LegacyUnit, dil=9) + 9 + 3 + 3 = 42，
  144:  * 取 H = 48。块 [u0-48, u1+48) 算完，[u0,u1) 这一段是精确的。
  145:  *
  146:  * 数值：这不是逐位一致改动 —— int8 dense-tile 的量化尺度是每 WT(默认 256) 个
  147:  * 输出位置共用一个，与子块边界耦合；blocks.c 里 conv_unit / first_block 的
  148:  * 分块早就是同样的性质。整段路径能分到内存时仍然走整段路径，本函数只在
  149:  * 整段 up 分配失败时生效，用 SNR 回归确认（见 _REALTIME_ROUND22_20260914.md）。 */
  150: static int decoder_tail_stream(const T *cur, int B, int dim_s, int nxt, int Tn, int scale,
  151:                                const float *wc, const float *bc,
  152:                                const float *wn, const float *bn, int last_dim, T *out)
  153: {
  154:     int U = Tn * scale;
  155:     out->ndim = 3; out->shape[0] = B; out->shape[1] = 1; out->shape[2] = U;
  156:     out->len = B * U;
  157:     float *nd = (float*)jx_arealloc(out->d, (size_t)out->len * sizeof(float));
  158:     if (nd == NULL)
  159:       {
  160:         jx_conv_skip++;
  161:         printf("[TLS] 末段输出 %d floats 分配失败\n", out->len);
  162:         out->d = NULL; out->len = 0; out->shape[2] = 0;
  163:         return -1;
  164:       }
  165:     out->d = nd;
  166:     if (B != 1)
  167:       {
  168:         jx_conv_skip++;
  169:         printf("[TLS] 只支持 B=1（当前 B=%d）\n", B);
  170:         out->len = 0; out->shape[2] = 0;
  171:         return -1;
  172:       }
  173: 
  174:     int W = dec_chunk_width();
  175:     if (W <= 0) { W = JX_CHUNK_DEFAULT; }
  176:     {   /* JX_TLSW 覆盖末段块宽（主机对照用；>= U 即单块，应当与整段路径逐位一致） */
  177:         const char *we = getenv("JX_TLSW");
  178:         if (we != NULL) { int v = atoi(we); if (v > 0) { W = v; } }
  179:     }
  180:     const int H = 48;
  181:     int cap    = W + 2 * H;
  182:     int cw_cap = (cap + scale - 1) / scale + 3;
  183: 
  184:     T xc  = t_alloc(3, (int[]){B, dim_s, cw_cap});
  185:     T uc  = t_alloc(3, (int[]){B, nxt,   cw_cap});
  186:     T yc  = t_alloc(3, (int[]){B, nxt,   cw_cap * scale});
  187:     T blk = t_alloc(3, (int[]){B, nxt,   cap});
  188:     T fin = t_alloc(3, (int[]){B, 1,     cap});
  189:     int rc = 0;
  190:     if (xc.d == NULL || uc.d == NULL || yc.d == NULL || blk.d == NULL || fin.d == NULL)
  191:       {
  192:         jx_conv_skip++;
  193:         printf("[TLS] 工作缓冲分配失败\n");
  194:         rc = -1; goto done;
  195:       }
  196:     {
  197:     const float *sn_a  = W_("decoder.blocks.13.block.1.alpha");
  198:     const float *fw    = W_("decoder.blocks.13.block.2.weight");
  199:     const float *fb    = W_("decoder.blocks.13.block.2.bias");
  200: 
  201:     for (int u0 = 0; u0 < U; u0 += W)
  202:       {
  203:         int u1 = u0 + W; if (u1 > U) { u1 = U; }
  204:         int a  = u0 - H; if (a  < 0) { a  = 0; }
  205:         int e  = u1 + H; if (e  > U) { e  = U; }
  206:         int w  = e - a;
  207:         /* up 的全局索引 g 只依赖 conv 域索引 floor(g/scale) 与 +1（线性插值，
  208:          * 见 upsampling_linear；kmod 的 itab 可能是 -1，所以左边必须多带 1 个
  209:          * conv 样点，否则块首会被钳到 cur[pa] 而不是真实的 cur[pa-1]）。 */
  210:         int pa = a / scale; if (pa > 0) { pa -= 1; }
  211:         int pb = (e >= U) ? Tn : ((e - 1) / scale + 2);
  212:         if (pb > Tn) { pb = Tn; }
  213:         int cw = pb - pa;
  214:         if (cw <= 0 || cw > cw_cap || w > cap)
  215:           {
  216:             jx_conv_skip++;
  217:             printf("[TLS] 窗口越界 cw=%d w=%d cap=%d\n", cw, w, cap);
  218:             rc = -1; goto done;
  219:           }
  220: 
  221:         xc.shape[0] = B; xc.shape[1] = dim_s; xc.shape[2] = cw; xc.len = B * dim_s * cw;
  222:         for (int c = 0; c < dim_s; c++)
  223:             memcpy(&xc.d[(size_t)c * cw], &cur->d[(size_t)c * Tn + pa],
  224:                    (size_t)cw * sizeof(float));
  225:         conv1d(wc, bc, &xc, &uc, dim_s, nxt, 1, 1, 0, 1, cw);
  226:         if (uc.len != B * nxt * cw)
  227:           { jx_conv_skip++; printf("[TLS] 1x1 卷积失败\n"); rc = -1; goto done; }
  228:         upsampling_linear(&uc, &yc, B, nxt, cw, scale);
  229:         if (yc.len == 0)
  230:           { jx_conv_skip++; printf("[TLS] 上采样失败\n"); rc = -1; goto done; }
  231: 
  232:         blk.shape[0] = B; blk.shape[1] = nxt; blk.shape[2] = w; blk.len = B * nxt * w;
  233:         int off = pa * scale;              /* yc 的第 off 列 == 全局 up 的第 pa*scale 列 */
  234:         for (int c = 0; c < nxt; c++)
  235:             memcpy(&blk.d[(size_t)c * w], &yc.d[(size_t)c * (cw * scale) + (a - off)],
  236:                    (size_t)w * sizeof(float));
  237:         channel_norm_first(&blk, wn, bn, B, nxt, w);
  238: 
  239:         for (int r = 0; r < 3; r++)
  240:           {
  241:             char rp[64];
  242:             snprintf(rp, sizeof(rp), "decoder.blocks.13.block.0.%d.module", r);
  243:             legacy_unit_add(&blk, rp, (r == 0 ? 1 : r == 1 ? 3 : 9));
  244:           }
  245:         snake1d(&blk, sn_a, B, w, last_dim, 0);
  246:         fin.shape[0] = B; fin.shape[1] = 1; fin.shape[2] = w; fin.len = B * w;
  247:         conv1d(fw, fb, &blk, &fin, last_dim, 1, 7, 1, 3, 1, w);
  248:         if (fin.len != B * w)
  249:           { jx_conv_skip++; printf("[TLS] 末层卷积失败\n"); rc = -1; goto done; }
  250:         jx_kt_ensure();
  251:         {   /* 第三十九轮：tanh 的 8 个系数装载一次 */
  252:             const jx_tanh8 TH = jx_tanh8_load();
  253:             for (int t = 0; t < u1 - u0; t++)
  254:                 out->d[(size_t)u0 + t] = jx_tanhf8(fin.d[(size_t)(u0 - a) + t], TH);
  255:         }
  256:       }
  257:     }
  258:   done:
  259:     t_free(&xc); t_free(&uc); t_free(&yc); t_free(&blk); t_free(&fin);
  260:     if (rc != 0) { out->len = 0; out->shape[2] = 0; }
  261:     return rc;
  262: }
