  264: /* ============================ modules.Decoder.forward ============================ */
  265: void decoder_forward(const T *x, T *out) {
  266:     JXP_BEG(JP_DECODER);
  267:     /* x[B,FEATURE_DIM,T'] -> out[B,1,T] (T = T'*HOP_LENGTH) */
  268:     int B = x->shape[0], T0 = x->shape[2];
  269:     /* 2026-09-14 第二十三轮（板端 5 秒崩机根因）：所有早退路径都必须留下一个
  270:      * "明确无效"的张量。原来中途 stage 失败时 out->d 是未初始化的栈垃圾，
  271:      * jx_decode 按 origT 去读 -> LoadProhibited（实测 PC=jx_decode+0x189，
  272:      * VADDR=0x25，栈里 dec={d=0x25,ndim=3,shape=1,1,0,len=0}）。 */
  273:     out->ndim = 3; out->shape[0] = B; out->shape[1] = 1; out->shape[2] = 0;
  274:     out->len = 0; out->d = NULL;
  275:     dec_mem("dec 入口", -1, T0);
  276:     /* 2026-09-14 第二十三轮：在堆最完整的时候（实测入口最大空闲块 7.59MB）
  277:      * 先把 up 路径要用的 1x1 卷积暂存张量 [B,nxt,Tn] 预留好。它比 up 小一个
  278:      * 数量级，不占后面唯一剩下的那块大内存；放这里是为了不让它去啃 stage 2
  279:      * 需要的那块 4.48MB 连续空间（见 decoder_up_path 的注释）。 */
  280:     T sc = t_alloc(3, (int[]){1, 1, 0});
  281:     {
  282:         int mx = 0;
  283:         for (int s = 0; s + 1 < DEC_STAGES; s++)
  284:           {
  285:             int Ts = T0;
  286:             for (int k = 0; k <= s; k++) { Ts *= DEC_STRIDES[k]; }
  287:             int f = B * DEC_DIMS[s + 1] * (Ts / DEC_STRIDES[s]);   /* B*nxt*Tn */
  288:             if (f > mx) { mx = f; }
  289:           }
  290:         if (mx > 0)
  291:           {
  292:             sc = t_alloc(3, (int[]){1, 1, mx});
  293:             printf("[MEMDEC] 预留 1x1 卷积暂存 %d floats (%.2fMB) %s\n",
  294:                    mx, (double)mx * 4.0 / 1.0e6, sc.d ? "成功" : "失败");
  295:           }
  296:     }
  297:     T cur = t_alloc(3, (int[]){B, FEATURE_DIM, T0}); t_copy(&cur, x);
  298:     /* block0: conv FEATURE_DIM -> DEC_DIMS[0] k=3 p=1 */
  299:     T c = t_alloc(3, (int[]){B, DEC_DIMS[0], 0});
  300:     conv1d(W_("decoder.blocks.0.weight"), W_("decoder.blocks.0.bias"), &cur, &c, FEATURE_DIM, DEC_DIMS[0], 3, 1, 1, 1, T0);
  301:     t_free(&cur); cur = c;
  302:     int Tn = cur.shape[2];
  303:     /* stage loop: each stage = [ConvUnit x DEC_DEPTHS[s]] + Enhance + Up.
  304:      * block indices are fixed across rates: stage s -> convu=1+3s,
  305:      * enh=2+3s, up_layer=3+3s (matches Python modules.Decoder). Extra
  306:      * ConvUnits for DEC_DEPTHS[s]>1 live at decoder.blocks.{convu}.{j}. */
  307:     for (int s = 0; s < DEC_STAGES; s++) {
  308:         /* 末段不再用卷积暂存（它的 uc_need = 768*T0 恒大于暂存的 448*T0），
  309:          * 而末段自己的 conv_unit 光分块临时块就要 1.84MB，先把暂存还回去。
  310:          * 主机 8.5MB 实测：不还，stage 3 的 conv_unit 就分不到那 1.84MB。 */
  311:         if (s == DEC_STAGES - 1) { t_free(&sc); }
  312:         int convu = 1 + 3 * s, enh = 2 + 3 * s;   /* up_layer = enh+1 = 3+3s */
  313:         int dim_s = DEC_DIMS[s];
  314:         /* per-stage ConvUnit(s); each is a residual add (depth>1 -> j loop) */
  315:         for (int j = 0; j < DEC_DEPTHS[s]; j++) {
  316:             char p[64]; snprintf(p, sizeof(p), "decoder.blocks.%d.%d.module", convu, j);
  317:             /* conv_unit_add 就地累加，省掉一整块 [dim_s,Tn]（4 秒音频 3.6MB） */
  318:             conv_unit_add(&cur, p);
  319:         }
  320:         /* enhance */
  321:         /* 2026-09-14 第二十一轮：enhance 就地写回 cur，省掉一整块 [dim,T]。
  322:          * 分支（trend-pool + merge_layer.0）都先算完，最后那句 y = x + merged*x
  323:          * 逐元素只读自己那一个元素，就地写完全等价（见 blocks.c enhance_block）。 */
  324:         char pe[64]; snprintf(pe, sizeof(pe), "decoder.blocks.%d", enh);
  325:         enhance_block(&cur, &cur, pe, dim_s);
  326:         /* cur 已经就地更新，不需要 t_free / 重新指向 */
  327:         /* up: conv (dim_s -> nextdim, k=1,s=1) + Upsample(scale) + ChannelNorm(first) */
  328:         int nxt = (s + 1 < DEC_STAGES) ? DEC_DIMS[s+1] : DEC_DIMS[DEC_STAGES];
  329:         int scale = DEC_STRIDES[s];
  330:         char cn[64]; snprintf(cn, sizeof(cn), "decoder.blocks.%d.0.weight", enh + 1);
  331:         char cb[64]; snprintf(cb, sizeof(cb), "decoder.blocks.%d.0.bias", enh + 1);
  332:         char nn[64]; snprintf(nn, sizeof(nn), "decoder.blocks.%d.2.weight", enh + 1);
  333:         char nb[64]; snprintf(nb, sizeof(nb), "decoder.blocks.%d.2.bias", enh + 1);
  334:         T up = t_alloc(3, (int[]){B, nxt, 0});
  335:         /* JX_TLS=1 强制最后一个 stage 走流式末段（主机对照 / 板端试验用）。 */
  336:         const char *tls_e = getenv("JX_TLS");
  337:         int force_tls = (tls_e != NULL && atoi(tls_e) != 0) && (s == DEC_STAGES - 1);
  338:         int rc_up = 0;
  339:         if (!force_tls)
  340:             rc_up = decoder_up_path(&cur, B, dim_s, nxt, Tn, scale,
  341:                                     W_(cn), W_(cb), W_(nn), W_(nb),
  342:                                     &sc, (s == DEC_STAGES - 1), &up);
  343:         if (rc_up != 0 || force_tls)
  344:           {
  345:             /* 整段 up 拿不到连续内存（长录音）。只有最后一个 stage 才能走流式
  346:              * 兜底：它直接产出 out，跳过后面的 decoder.blocks.13。 */
  347:             if (s == DEC_STAGES - 1)
  348:               {
  349:                 printf("[DEC] %s（Tn=%d scale=%d），转流式末段\n",
  350:                        force_tls ? "JX_TLS 强制流式末段" : "末段整段 up 分配失败", Tn, scale);
  351:                 dec_mem("末段流转前", s, Tn);
  352:                 T tls = t_alloc(3, (int[]){B, 1, 0});
  353:                 /* 失败时 decoder_tail_stream 已经把 tls 标成 len=0 并抬了
  354:                  * jx_conv_skip，调用方据此判“本次结果无效”。 */
  355:                 (void)decoder_tail_stream(&cur, B, dim_s, nxt, Tn, scale,
  356:                                           W_(cn), W_(cb), W_(nn), W_(nb),
  357:                                           DEC_DIMS[DEC_STAGES], &tls);
  358:                 t_free(&sc); t_free(&up); t_free(&cur);
  359:                 *out = tls;
  360:                 JXP_END(JP_DECODER);
  361:                 return;
  362:               }
  363:             jx_conv_skip++;
  364:             dec_mem("stage up 失败", s, Tn);
  365:             printf("[DEC] stage %d 的 up 分配失败，无法继续\n", s);
  366:             t_free(&sc); t_free(&up); t_free(&cur);
  367:             out->ndim = 3; out->shape[0] = B; out->shape[1] = 1; out->shape[2] = 0; out->len = 0;
  368:             JXP_END(JP_DECODER);
  369:             return;
  370:           }
  371:         t_free(&cur); cur = up; Tn = cur.shape[2];
  372:         dec_mem("stage 出", s, Tn);
  373:     }
  374:     /* legacy last block (decoder.blocks.13): 3x Residual(LegacyUnit) + Snake + conv(DEC_DIMS[DEC_STAGES]->1) + Tanh */
  375:     int last_dim = DEC_DIMS[DEC_STAGES];
  376:     for (int r = 0; r < 3; r++) {
  377:         char rp[64]; snprintf(rp, sizeof(rp), "decoder.blocks.13.block.0.%d.module", r);
  378:         /* 2026-09-14 第二十一轮：改成时间分块 + 就地累加（blocks.c legacy_unit_add）。
  379:          * 整段展开时 cur/lu/s0/c1 四块 [1,16,T] 同时活着，2 秒音频就是 8.2MB，
  380:          * 超过 PSRAM 堆总量 -> conv1d_d 的 realloc 必失败、卷积被跳过。数值逐位不变。 */
  381:         legacy_unit_add(&cur, rp, (r == 0 ? 1 : r == 1 ? 3 : 9));
  382:     }
  383:     /* 2026-09-13 第九轮：原来先把 cur 整块复制到 sn 再就地 snake。
  384:      * cur 在这之后只被 free，没有任何读者，直接原地 snake 即可
  385:      * （T=16032 时省掉 2MB 往返，数值不变）。 */
  386:     snake1d(&cur, W_("decoder.blocks.13.block.1.alpha"), B, Tn, last_dim, 0);
  387:     T fin = t_alloc(3, (int[]){B, 1, 0}); conv1d(W_("decoder.blocks.13.block.2.weight"), W_("decoder.blocks.13.block.2.bias"), &cur, &fin, last_dim, 1, 7, 1, 3, 1, Tn);
  388:     JXP_BEG(JP_GELU);
  389:     jx_kt_ensure();
  390:     { const jx_tanh8 TH = jx_tanh8_load();
  391:       for (int i = 0; i < fin.len; i++) fin.d[i] = jx_tanhf8(fin.d[i], TH); }
  392:     JXP_END(JP_GELU);
  393:     t_free(&sc);
  394:     t_free(&cur); *out = fin;
  395:     JXP_END(JP_DECODER);
  396: }
