  398: /* ============================ LocalDecoder.forward ============================ */
  399: void en_decoder_forward(const T *x, T *out) {
  400:     JXP_BEG(JP_ENDECODER);
  401:     /* x[B,T',C] -> LocalTrans stack -> permute [B,C,T'] */
  402:     int B = x->shape[0], Tt = x->shape[1], C = x->shape[2];
  403: 
  404:     if (EN_USE_COMPRESSED) {
  405:         /* CompressedLocalDecoderWithCache:
  406:          *   local_trans = LocalTrans(depth=EN_DEC_LOCAL_DEPTH, win=EN_DEC_LOCAL_WIN)
  407:          *                (depth 0 -> identity for 1kbps)
  408:          *   up_trans = Upsample(scale=rate) then LocalTrans(depth=EN_DEC_UP_DEPTH, win=EN_DEC_UP_WIN) */
