  172:               { ks16[(size_t)h * (size_t)Tn + a] = jx_qrow_i16(&kb[(size_t)a*dh], kq16 + ((size_t)h * (size_t)Tn + a)*16u, dh); }
  173:           }
  174:         if (qk_i8)
  175:           {
  176:             const float *kb = &kp.d[(size_t)(bi*heads+h)*n_pad*dh];
  177:             for (int a = 0; a < Tn; a++)
  178:               { ks[(size_t)h * (size_t)Tn + a] = jx_qrow_i8(&kb[(size_t)a*dh], kq + ((size_t)h * (size_t)Tn + a)*16u, dh); }
  179:           }
  180:     }
  181: }
  182: 
  183: JX_HOT static void jx_lmha_hh(void *va, int hlo, int hhi)
  184: {
  185:     jx_lmha_t *C = (jx_lmha_t *)va;
  186:     const int bi = C->bi, Tn = C->Tn, dh = C->dh;
  187:     const int heads = C->heads, n_pad = C->n_pad, window = C->window;
  188:     const int vstride = C->vstride;
  189:     const int qk_i8 = C->qk_i8, qk_i16 = C->qk_i16, sv_i8 = C->sv_i8;
  190:     T qp = *C->qp, kp = *C->kp, vp = *C->vp, op = *C->op;
  191:     const float *bias_tab = C->bias_tab;
  192:     signed char *kq = C->kq, *vT = C->vT;
  193:     float *ks = C->ks, *sv = C->sv;
  194:     signed short *kq16 = C->kq16; float *ks16 = C->ks16;
  195:     float sims[2 * window]; float ws[2 * window];
  196:     int32_t accs[2 * window];
  197:     (void)vstride;
  198:     for (int h = hlo; h < hhi; h++)
  199:     {
  200:         signed char *wsb = C->wsb + (size_t)h * (size_t)vstride;
  201:         for (int t = 0; t < Tn; t++)
  202:         {
  203:             int w = t / window;
  204:             int wstart = (w > 0) ? (w - 1) * window : 0;
  205:             (void)w;
  206:             float qi[dh]; for (int d = 0; d < dh; d++) qi[d] = qp.d[((bi*heads+h)*n_pad+t)*dh+d];
  207:             /* 2026-09-13 第六轮：QKᵀ 的原始写法每个 key 只有一条串行累加链
  208:              * （s += ...），而 Xtensa 的 madd.s 延迟 ~9 周期（单链实测
  209:              * 9.3 周期/MAC）。这里把 key 展开 2 路、d 也拆 2 路 = 4 条独立链，
  210:              * 让 FPU 流水线填满（8 链微基准 3.86 周期/MAC）。
  211:              * 代价是求和次序变化（浮点结合律不成立），token 可能有极少数
  212:              * 抖动，由 SNR 门禁守；dh 在本模型恒为偶数。 */
  213:             float mx = -1e30f;
  214:             int a = wstart;
  215:             if (qk_i16)
  216:               {
  217:                 signed short q16v[16] __attribute__((aligned(16)));
  218:                 float sq = jx_qrow_i16(&qp.d[(size_t)(bi*heads+h)*n_pad*dh + (size_t)t*dh], q16v, dh);
  219:                 int nk = t - wstart + 1;
  220:                 jx_qk_i16(q16v, kq16 + ((size_t)h * (size_t)Tn + wstart) * 16u, nk, accs);
  221:                 for (int i = 0; i < nk; i++)
  222:                   {
  223:                     float s = (float)accs[i] * (sq * ks16[(size_t)h * (size_t)Tn + wstart + i])
  224:                               + bias_tab[(size_t)(t - wstart - i) * heads + h];
  225:                     sims[i] = s; if (s > mx) { mx = s; }
  226:                   }
  227:     #ifdef COUNT_MACS
  228:                 g_attn_macs += (long long)nk * dh;
  229:     #endif
  230:               }
  231:             else if (qk_i8)
  232:               {
  233:                 signed char q16[16] __attribute__((aligned(16)));
  234:                 float sq = jx_qrow_i8(&qp.d[(size_t)(bi*heads+h)*n_pad*dh + (size_t)t*dh], q16, dh);
  235:                 int nk = t - wstart + 1;
  236:                 jx_qk_i8(q16, kq + ((size_t)h * (size_t)Tn + wstart) * 16u, nk, accs);
  237:                 for (int i = 0; i < nk; i++)
  238:                   {
  239:                     float s = (float)accs[i] * (sq * ks[(size_t)h * (size_t)Tn + wstart + i])
  240:                               + bias_tab[(size_t)(t - wstart - i) * heads + h];
  241:                     sims[i] = s; if (s > mx) mx = s;
  242:                   }
  243:     #ifdef COUNT_MACS
  244:                 g_attn_macs += (long long)nk * dh;
  245:     #endif
  246:               }
  247:             else
  248:             for (; dh >= 2 && a + 1 <= t; a += 2) {
  249:                 const float *k0 = &kp.d[((bi*heads+h)*n_pad+a)*dh];
  250:                 const float *k1 = &kp.d[((bi*heads+h)*n_pad+a+1)*dh];
  251:                 float s0 = 0, s0b = 0, s1 = 0, s1b = 0;
  252:                 int d = 0;
  253:                 for (; d + 1 < dh; d += 2) {
  254:                     s0  += qi[d]     * k0[d];
  255:                     s0b += qi[d + 1] * k0[d + 1];
  256:                     s1  += qi[d]     * k1[d];
  257:                     s1b += qi[d + 1] * k1[d + 1];
  258:     #ifdef COUNT_MACS
  259:                     g_attn_macs += 4;
  260:     #endif
  261:                 }
  262:                 for (; d < dh; d++) { s0 += qi[d] * k0[d]; s1 += qi[d] * k1[d];
  263:     #ifdef COUNT_MACS
  264:                     g_attn_macs += 2;
  265:     #endif
  266:                 }
  267:                 { float v0 = (s0 + s0b) + bias_tab[(size_t)(t - a) * heads + h];
  268:                   float v1 = (s1 + s1b) + bias_tab[(size_t)(t - a - 1) * heads + h];
  269:                   sims[a - wstart] = v0; if (v0 > mx) mx = v0;
  270:                   sims[a - wstart + 1] = v1; if (v1 > mx) mx = v1; }
  271:             }
  272:             for (; !qk_i8 && !qk_i16 && a <= t; a++) {
  273:                 float s = 0; for (int d = 0; d < dh; d++) { s += qi[d] * kp.d[((bi*heads+h)*n_pad+a)*dh+d];
  274:     #ifdef COUNT_MACS
  275:                 g_attn_macs++;   /* QKᵀ: 每个 (d,a) 一次乘加 */
  276:     #endif
  277:                 }
  278:                 s += bias_tab[(size_t)(t - a) * heads + h];
  279:                 sims[a - wstart] = s; if (s > mx) mx = s;
  280:             }
  281:             float sum = 0; int kc = t - wstart + 1;
  282:             /* 2026-09-13 第六轮：软 max 之后 exp 的入参恒 <= 0，用多项式版
  283:              * jx_expf_neg 替代 libm expf（本处调用量 1560 万次，是全模型
  284:              * 单点最大的超越函数开销）。 */
  285:             for (int a = wstart; a <= t; a++) { ws[a - wstart] = jx_expf_neg(sims[a - wstart] - mx); JX_EXP_CNT(); sum += ws[a - wstart]; }
  286:             float inv = (sum > 0) ? 1.0f / sum : 0.f;
  287:             if (sv_i8)
  288:               {
  289:                 /* attn·V 的 int8 路径：w（softmax 权重，<=1，scale 恒 127）
  290:                  * 按行量化，v 已按列量化并转置；每 16 个 key 一条
  291:                  * ee.vmulas.s8.accx 完成"沿 key 维求和"。 */
  292:                 int nk = t - wstart + 1;
  293:                 int nblk = (nk + 15) >> 4;
  294:                 for (int i = 0; i < nk; i++)
  295:                   {
  296:                     float wv = ws[i] * 127.0f;
  297:                     int iv = (int)(wv + 0.5f);
  298:                     if (iv > 127) { iv = 127; } else if (iv < 0) { iv = 0; }
  299:                     wsb[i] = (signed char)iv;
  300:                   }
  301:                 for (int i = nk; i < (nblk << 4); i++) { wsb[i] = 0; }
  302:                 for (int d = 0; d < dh; d++)
  303:                   {
  304:                     int32_t acc = jx_sv_i8(wsb,
  305:                         vT + ((size_t)h * (size_t)dh + (size_t)d) * (size_t)vstride + wstart, nblk);
  306:                     op.d[((bi*heads+h)*n_pad+t)*dh+d] =
  307:                         (float)acc * (sv[(size_t)h * (size_t)dh + d] * (1.0f / 127.0f)) * inv;
  308:     #ifdef COUNT_MACS
  309:                     g_attn_macs += nk;
  310:     #endif
  311:                   }
  312:               }
  313:             else
  314:             /* 同样的问题：每个 d 一条串行链。改成 d 展开 2 路 + a 折半
  315:              * 各 2 条链 = 4 条独立链；末尾奇数 d / 空半段用尾循环兜住。 */
  316:             {
  317:                 int d = 0;
  318:                 for (; dh >= 2 && d + 1 < dh; d += 2) {
  319:                     int mid = wstart + (t - wstart + 1) / 2;
  320:                     float a0 = 0, a1 = 0, c0 = 0, c1 = 0;
  321:                     int aa = wstart;
  322:                     for (; aa < mid; aa++) {
  323:                         const float *vv = &vp.d[((bi*heads+h)*n_pad+aa)*dh+d];
  324:                         float w = ws[aa - wstart];
  325:                         a0 += w * vv[0]; a1 += w * vv[1];
  326:     #ifdef COUNT_MACS
  327:                         g_attn_macs += 2;
  328:     #endif
  329:                     }
  330:                     for (; aa <= t; aa++) {
  331:                         const float *vv = &vp.d[((bi*heads+h)*n_pad+aa)*dh+d];
  332:                         float w = ws[aa - wstart];
  333:                         c0 += w * vv[0]; c1 += w * vv[1];
  334:     #ifdef COUNT_MACS
  335:                         g_attn_macs += 2;
  336:     #endif
  337:                     }
  338:                     op.d[((bi*heads+h)*n_pad+t)*dh+d]     = (a0 + c0) * inv;
  339:                     op.d[((bi*heads+h)*n_pad+t)*dh+d + 1] = (a1 + c1) * inv;
  340:                 }
  341:                 for (; d < dh; d++) {
  342:                     float acc = 0;
  343:                     for (int aa = wstart; aa <= t; aa++) { acc += ws[aa - wstart] * vp.d[((bi*heads+h)*n_pad+aa)*dh+d];
  344:     #ifdef COUNT_MACS
  345:                         g_attn_macs++;
  346:     #endif
  347:                     }
  348:                     op.d[((bi*heads+h)*n_pad+t)*dh+d] = acc * inv;
  349:                 }
  350:             }
  351:         }
  352:     }
  353: }
  354: 
  355: static void local_mha_layer(const T *x, T *out, const char *pfx, const char *tpfx, int window) {
  356:     int B = x->shape[0], Tn = x->shape[1], C = x->shape[2];
  357:     /* Head config is rate-specific and is READ FROM THE WEIGHTS (not hardcoded):
  358:        to_qkv produces inner*3 channels  -> inner = to_qkv.weight.shape[0] / 3 ;
  359:        the shared DynamicPositionBias MLP emits one bias per head, so its final
  360:        linear's out-dim == heads.  dim_head = inner / heads.  This keeps the
  361:        transformer correct for every rate (e.g. 3kbps 64-dim/6h/16d vs 1kbps
  362:        56-dim) without per-rate head constants in model_config. */
  363:     int qkv_shape[4], qkv_n;
  364:     wt_get(cat_name(pfx, "to_qkv.weight"), qkv_shape, &qkv_n);
  365:     int inner = qkv_shape[0] / 3;
  366:     int dpb_shape[4], dpb_n;
  367:     wt_get(cat_name(tpfx, "dynamic_pos_bias.mlp.4.weight"), dpb_shape, &dpb_n);
  368:     int heads = dpb_shape[0], dh = inner / heads;
  369: #ifdef COUNT_MACS
  370:     g_attn_heads = heads;
  371: #endif
  372:     int dpb0_shape[4], dpb0_n;
  373:     wt_get(cat_name(tpfx, "dynamic_pos_bias.mlp.0.weight"), dpb0_shape, &dpb0_n);
  374:     int dpb_H = dpb0_shape[0];   /* DynamicPositionBias hidden dim = feature_dim//2 (rate-dependent) */
  375:     /* DynamicPositionBias MLP weights live at the transformer root (sibling of `layers`), not in the layer. */
  376:     const float *pb_w0 = W_(cat_name(tpfx, "dynamic_pos_bias.mlp.0.weight")), *pb_b0 = W_(cat_name(tpfx, "dynamic_pos_bias.mlp.0.bias"));
  377:     const float *pb_w1 = W_(cat_name(tpfx, "dynamic_pos_bias.mlp.2.weight")), *pb_b1 = W_(cat_name(tpfx, "dynamic_pos_bias.mlp.2.bias"));
  378:     const float *pb_w2 = W_(cat_name(tpfx, "dynamic_pos_bias.mlp.4.weight")), *pb_b2 = W_(cat_name(tpfx, "dynamic_pos_bias.mlp.4.bias"));
  379:     T xn = t_alloc(3, (int[]){B, Tn, C}); t_copy(&xn, x);
  380:     channel_norm_last(&xn, W_(cat_name(pfx, "norm.weight")), W_(cat_name(pfx, "norm.bias")), B, Tn, C);
  381:     T qkv = t_alloc(3, (int[]){B, Tn, inner * 3});
  382:     linear(W_(cat_name(pfx, "to_qkv.weight")), NULL, &xn, &qkv, C, inner * 3);
  383:     float scale = 1.0f / sqrtf((float)dh);
  384:     int n_pad = ((Tn + window - 1) / window) * window;
  385:     T qp = t_alloc(4, (int[]){B, heads, n_pad, dh}); T kp = t_alloc(4, (int[]){B, heads, n_pad, dh}); T vp = t_alloc(4, (int[]){B, heads, n_pad, dh});
  386:     for (int bi = 0; bi < B; bi++) for (int t = 0; t < n_pad; t++) {
  387:         int ts = (t < Tn) ? t : 0;
  388:         for (int h = 0; h < heads; h++) for (int d = 0; d < dh; d++) {
  389:             int idx = (bi * Tn + ts) * (inner * 3) + h * dh + d;   /* qkv row width is inner*3 */
  390:             qp.d[((bi*heads+h)*n_pad+t)*dh+d] = qkv.d[idx] * scale;
  391:             kp.d[((bi*heads+h)*n_pad+t)*dh+d] = qkv.d[idx + inner];
  392:             vp.d[((bi*heads+h)*n_pad+t)*dh+d] = qkv.d[idx + 2*inner];
  393:         }
  394:     }
  395:     T op = t_alloc(4, (int[]){B, heads, n_pad, dh});
  396:     /* window=400, look_backward=1, look_forward=0, causal=True (local_attention lib):
  397:        look_around() includes the FULL previous window as keys (look_backward=1 => prev 1 window),
  398:        not just the previous token. Combined with the causal mask (bq_t < bq_k), each query t in
  399:        window w sees keys a in [(w-1)*W, t], where w = floor(t/W) and the lower bound is clamped
  400:        to 0 in the first window. Bias b(h,t,a) = DynamicPositionBias.mlp(t - a).
  401:        Verified against local_attention.LocalAttention mask for window-start queries (e.g. t=400
  402:        sees [0,400]) and generalized: the whole previous window is visible to every query. */
  403:     /* DynamicPositionBias depends ONLY on the relative distance t-a, so hoist the
  404:      * MLP out of the (head, key) loops: precompute one row per distance
  405:      * 0..2*window-1. The original recomputed the full MLP for every
  406:      * (token, head, key) triple, which cost ~39x the actual QK^T/attn.V math and
  407:      * dominated the whole codec compute budget. Max distance is t-wstart =
  408:      * 2*window-1, so n_rel = 2*window covers every case. */
  409:     JX_EXP_ARM();
  410:     int n_rel = 2 * window;
  411:     float *bias_tab = (float*)malloc(sizeof(float) * (size_t)n_rel * (size_t)heads);
  412:     for (int r = 0; r < n_rel; r++)
  413:         dpb_mlp(pb_w0, pb_b0, pb_w1, pb_b1, pb_w2, pb_b2,
  414:                 (float)r, &bias_tab[(size_t)r * heads], heads, dpb_H);
  415: 
  416:     /* 2026-09-13 第七轮：QKᵀ 的 int8 化（dh 恰好 = 一个 128-bit 向量）。
  417:      * k 按 (bi,h) 量化进 slab（每行 16 字节 + 一个 scale），q 逐行即时量化；
  418:      * 点积走 jx_qk_i8（每 key 一条 ee.vmulas.s8.accx）。量化开销被
  419:      * 每个 key 行被 2*window 个 query 复用摊掉。失败即退回 fp32 路径。 */
  420:     int qk_i8 = (dh == 16) ? jx_attn_qk_i8_enabled() : 0;   /* 默认关（精度不足） */
  421:     int qk_i16 = (dh == 16) ? jx_attn_qk_i16_enabled() : 0;   /* 默认开（13 位 int16） */
  422:     int sv_i8 = (dh == 16 && (window % 16) == 0) ? jx_attn_sv_i8_enabled() : 0;
  423:     signed short *kq16 = NULL;  float *ks16 = NULL;
  424:     signed char *kq = NULL;  float *ks = NULL;
  425:     signed char *vT = NULL;  float *sv = NULL;  signed char *wsb = NULL;
  426:     void *raw_v = NULL, *raw_w = NULL;   /* vT/wsb 的对齐前指针，free 必须用它们 */
  427:     /* vT 行距取 16 的倍数（PIE 128-bit 装载必须 16 字节对齐），
  428:      * 且多留 16 字节做零填充（最后一个 block 可能读到 t 之后）。 */
  429:     int vstride = ((Tn + 31) / 16) * 16;
  430:     if (qk_i8)
  431:       {
  432:         /* r176：kq 每行 16 字节，jx_qk_i8 用 ee.vld.128 按 16 字节步长装载 ——
  433:          * malloc 只保证 8 字节对齐，未对齐时读到的 key 全是错位的。 */
  434:         kq = (signed char *)jx_amalloc((size_t)Tn * 16u * (size_t)heads);
  435:         ks = (float *)malloc((size_t)Tn * sizeof(float) * (size_t)heads);
  436:         if (kq == NULL || ks == NULL) { jx_afree(kq); free(ks); kq = NULL; ks = NULL; qk_i8 = 0; }
  437:       }
  438:     if (qk_i16)
  439:       {
  440:         /* r176：kq16 每个 key 占 16 个 short = 32 字节，jx_qk_i16 用两条
  441:          * ee.vld.128 按 32 字节步长装载 —— 同样要求基址 16 字节对齐。
  442:          * 板端实测未对齐（0x...c88, mod16=8）会让编码端 en_encoder 输出
  443:          * 随堆布局漂移，这就是单核/双核结果不一致的根因。 */
  444:         kq16 = (signed short *)jx_amalloc((size_t)Tn * 16u * sizeof(signed short) * (size_t)heads);
  445:         ks16 = (float *)malloc((size_t)Tn * sizeof(float) * (size_t)heads);
  446:         if (kq16 == NULL || ks16 == NULL) { jx_afree(kq16); free(ks16); kq16 = NULL; ks16 = NULL; qk_i16 = 0; }
  447:       }
  448:     if (sv_i8)
  449:       {
  450:         raw_v = malloc((size_t)vstride * (size_t)dh * (size_t)heads + 32u);
  451:         raw_w = malloc((size_t)vstride * (size_t)heads + 32u);
  452:         vT  = (raw_v != NULL) ? (signed char *)(((uintptr_t)raw_v + 15u) & ~(uintptr_t)15u) : NULL;
  453:         wsb = (raw_w != NULL) ? (signed char *)(((uintptr_t)raw_w + 15u) & ~(uintptr_t)15u) : NULL;
  454:         sv  = (float *)malloc(sizeof(float) * (size_t)dh * (size_t)heads);
  455:         if (vT == NULL || wsb == NULL || sv == NULL)
  456:           { free(raw_v); free(raw_w); free(sv); raw_v = NULL; raw_w = NULL; vT = NULL; wsb = NULL; sv = NULL; sv_i8 = 0; }
  457:       }
  458:     jx_lmha_t LMC;
  459:     LMC.B = B; LMC.Tn = Tn; LMC.inner = inner; LMC.heads = heads; LMC.dh = dh;
  460:     LMC.n_pad = n_pad; LMC.window = window; LMC.vstride = vstride; LMC.bi = 0;
  461:     LMC.qp = &qp; LMC.kp = &kp; LMC.vp = &vp; LMC.op = &op;
  462:     LMC.bias_tab = bias_tab;
  463:     LMC.kq = kq; LMC.ks = ks; LMC.kq16 = kq16; LMC.ks16 = ks16;
  464:     LMC.vT = vT; LMC.sv = sv; LMC.wsb = wsb;
  465:     LMC.qk_i8 = qk_i8; LMC.qk_i16 = qk_i16; LMC.sv_i8 = sv_i8;
  466:     for (int bi = 0; bi < B; bi++)
  467:       {
  468:         LMC.bi = bi;
  469:         jx_pf_run_min(heads, jx_lmha_prep, &LMC, 2);
  470:         jx_pf_run_min(heads, jx_lmha_hh, &LMC, 2);
  471:       }
  472:     T o2trim = t_alloc(3, (int[]){B, Tn, inner});
  473:     for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tn; t++) for (int h = 0; h < heads; h++) for (int d = 0; d < dh; d++)
  474:         o2trim.d[(bi*Tn+t)*inner + h*dh+d] = op.d[((bi*heads+h)*n_pad+t)*dh+d];
  475:     out->shape[0] = B; out->shape[1] = Tn; out->shape[2] = C; out->len = B*Tn*C;
  476:     linear(W_(cat_name(pfx, "to_out.weight")), NULL, &o2trim, out, inner, C);
  477:     t_free(&xn); t_free(&qkv); t_free(&qp); t_free(&kp); t_free(&vp); t_free(&op); t_free(&o2trim);
  478:     free(bias_tab);
  479:     jx_afree(kq); free(ks);
  480:     jx_afree(kq16); free(ks16);
  481:     free(sv); free(raw_v); free(raw_w);
  482: }
