   51: /* ==================== r69：分块拷贝 / 累加的并行化 ====================
   52:  * first_block / conv_unit / conv_unit_add / legacy_unit_add 都用"时间分块 +
   53:  * halo"把一个 [C,T] 张量切成 [C,w] 的小块喂给 core。包在 core 外面的
   54:  * gather / scatter / save / 逐元素累加循环是纯搬运，原来全在单核上跑、
   55:  * 而且完全没有被任何计时桶覆盖。这里按通道切给双核，并把耗时记进 JP_MISC。
   56:  * 每个元素写入的值与原来逐项一致 -> 结果逐位不变。 */
   57: typedef struct {
   58:     const T *src; float *dst; const float *save;
   59:     int C, Tt, bi, a, w, saved_from, H;
   60:     int split_t;   /* r121：C==1 的单通道整段搬运，按时间维切给两核 */
   61: } jx_glue_g_t;
   62: 
   63: /* 把 x[bi][c][a .. a+w) 收进连续缓冲 dst[c][0 .. w)。saved_from >= 0 时，
   64:  * [saved_from, saved_from+H) 这一段取 save 里的"加之前"的原值。 */
   65: JX_HOT static void jx_glue_gather(void *va, int clo, int chi)
   66: {
   67:     jx_glue_g_t *g = (jx_glue_g_t *)va;
   68:     const int C = g->C, Tt = g->Tt, a = g->a, w = g->w, H = g->H;
   69:     const int sf = g->saved_from;
   70:     const float *base = &g->src->d[(size_t)g->bi * C * Tt];
   71:     /* r121：first_block 的 gather 只有一个通道（C==1），原来只能传 n=1
   72:      * 强制单核串行跑完整段 memcpy。这里允许按**时间维**切分：clo/chi 解释为
   73:      * [a, a+w) 内的偏移区间。搬运的字节与逐元素结果完全相同。 */
   74:     if (g->split_t)
   75:       {
   76:         const float *xd = base;
   77:         float *dst = g->dst;
   78:         for (int t = a + clo; t < a + chi; t++) { dst[t - a] = xd[t]; }
   79:         return;
   80:       }
   81:     for (int c = clo; c < chi; c++)
   82:       {
   83:         if (c + 1 < chi) { jx_dcp_pf_ew(base + (size_t)(c + 1) * Tt + a, (unsigned)w * 4u); }
   84:         const float *xd = base + (size_t)c * Tt;
   85:         float *dst = &g->dst[(size_t)c * w];
   86:         if (sf < 0)
   87:           {
   88:             memcpy(dst, xd + a, (size_t)w * sizeof(float));
   89:           }
   90:         else
   91:           {
   92:             const float *sv = g->save + (size_t)c * H;
   93:             for (int t = a; t < a + w; t++)
   94:               {
   95:                 dst[t - a] = (t >= sf && t < sf + H) ? sv[t - sf] : xd[t];
   96:               }
   97:           }
   98:       }
   99: }
  100: 
  101: typedef struct { float *dst; const float *src; int C, Tt, bi, t0, n, off, stride, add; } jx_glue_s_t;
  102: 
  103: /* 连续缓冲 src[c][off .. off+n) -> x[bi][c][t0 .. t0+n)，add!=0 时累加。 */
  104: JX_HOT static void jx_glue_scatter(void *va, int clo, int chi)
  105: {
  106:     jx_glue_s_t *g = (jx_glue_s_t *)va;
  107:     const int C = g->C, Tt = g->Tt, t0 = g->t0, n = g->n, off = g->off;
  108:     float *base = &g->dst[(size_t)g->bi * C * Tt];
  109:     for (int c = clo; c < chi; c++)
  110:       {
  111:         if (c + 1 < chi)
  112:           { jx_dcp_pf_ew(&g->src[(size_t)(c + 1) * (size_t)g->stride + off], (unsigned)n * 4u); }
  113:         float *dp = base + (size_t)c * Tt + t0;
  114:         const float *sp = &g->src[(size_t)c * (size_t)g->stride + off];
  115:         if (g->add)
  116:           { for (int t = 0; t < n; t++) { dp[t] += sp[t]; } }
  117:         else
  118:           { memcpy(dp, sp, (size_t)n * sizeof(float)); }
  119:       }
  120: }
  121: 
  122: typedef struct { const float *src; float *save; int C, Tt, bi, ns, n, H; } jx_glue_v_t;
  123: 
  124: /* x[bi][c][ns .. ns+n) -> save[c][0 .. n)  （n <= H） */
  125: JX_HOT static void jx_glue_save(void *va, int clo, int chi)
  126: {
  127:     jx_glue_v_t *g = (jx_glue_v_t *)va;
  128:     const float *base = &g->src[(size_t)g->bi * g->C * g->Tt];
  129:     for (int c = clo; c < chi; c++)
  130:       {
  131:         memcpy(g->save + (size_t)c * g->H,
  132:                base + (size_t)c * g->Tt + g->ns, (size_t)g->n * sizeof(float));
  133:       }
  134: }
