  136: /* ============================ shared trend extraction ============================ */
  137: /* max_pool1d(|x|, kernel, stride=1, padding) clamped at edges, then
  138:  * avg_pool1d(..., count_include_pad=True). Used by V3FirstBlock and
  139:  * EnhanceBlock to derive the "trend" branch of each module. */
  140: typedef struct { const float *x; float *y; int T_in, p, kernel; } jx_tp_t;
  141: 
  142: /* r68: split channels across the two cores. Each core owns its own m/dq
  143:  * scratch (the original shared one). Channels are fully independent, so the
  144:  * result is bit-identical to the serial version. */
  145: static void jx_tp_range(void *va, int clo, int chi) {
  146:     jx_tp_t *cc = (jx_tp_t *)va;
  147:     const float *x = cc->x; float *y = cc->y;
  148:     const int T_in = cc->T_in, p = cc->p, kernel = cc->kernel;
  149:     /* r71：原来每次调用都 malloc/free 两块 T_in 大小的 scratch；trend_pool 在
  150:      * 一次编解码里要进 28 次（first_block 5 条分支 x4 批 + enhance），每次都走
  151:      * 一趟堆。改成按核常驻、按需增长。缓冲只在本函数内使用、每次重写，
  152:      * 与原来的行为完全一致。 */
  153:     static float *s_m [JX_NCORE];
  154:     static int   *s_dq[JX_NCORE];
  155:     static int    s_cap[JX_NCORE];
  156:     int core = jx_core_id();
  157:     if (s_cap[core] < T_in)
  158:       {
  159:         float *nm = (float*)realloc(s_m [core], (size_t)T_in * sizeof(float));
  160:         int   *nd = (int  *)realloc(s_dq[core], (size_t)T_in * sizeof(int));
  161:         if (nm == NULL || nd == NULL) { return; }
  162:         s_m[core] = nm; s_dq[core] = nd; s_cap[core] = T_in;
  163:       }
  164:     float *m  = s_m [core];
  165:     int   *dq = s_dq[core];
  166:     for (int c = clo; c < chi; c++) {
  167:         const float *xc = &x[c * T_in]; float *yc = &y[c * T_in];
  168:         /* max_pool1d(|x|, kernel, stride=1, padding=p): 单调队列 O(T)。
  169:          * 边缘 clamp 时重复的边界值不会改变最大值，因此等价于在
  170:          * [max(0,t-p), min(T-1,t+p)] 上求最大值。比较顺序不影响 max 结果。 */
  171:         int head = 0, tail = 0;
  172:         int prev_r = -1;
  173:         for (int t = 0; t < T_in; t++) {
  174:             int l = t - p; if (l < 0) l = 0;
  175:             int r = t + p; if (r >= T_in) r = T_in - 1;
  176:             if (r > prev_r) {
  177:                 float av = fabsf(xc[r]);
  178:                 while (tail > head) {
  179:                     int idx = dq[tail - 1];
  180:                     if (fabsf(xc[idx]) <= av) { tail--; } else { break; }
  560: static int chunk_width(void);   /* 定义在文件下方的“时间分块执行”一节 */
  561: 
  562: /* 允许 y == x：4 条 trend-pool 分支都已经先算完，最后那个逐元素
  563:  * y = x + merged*x 只读自己那一个元素，就地写完全等价。
  564:  * 解码器各 stage 靠这一点省掉一整块 [dim,T]（3 秒音频 2.7MB）。 */
  565: void enhance_block(const T *x, T *y, const char *pfx, int dim) {
  566:     JXP_BEG(JP_ENHANCE);
  567:     /* EnhanceBlock(dim): 4 trendpool branches (xi=x[:,0:1]) -> cat(4ch) ->
  568:        InstanceNorm(4) -> Conv1d(4->dim) = merge_layer; then y = x + y*x ; out[B,dim,Tt] */
  569:     int B = x->shape[0], Tt = x->shape[2];
  570:     const int ps[4] = {1,3,5,9}; const int ks[4] = {7,7,7,7}; const int dr[4] = {1,2,3,5};
  571:     T h = t_alloc(3, (int[]){B, 4, Tt});
  572:     {   /* r81：4 条分支二分给两核 */
  573:         jx_enh_t ec; ec.x = &x->d[0 * Tt]; ec.h = h.d; ec.pfx = pfx; ec.Tt = Tt;
  574:         jx_pf_run_min(4, jx_enh_range, &ec, 2);
  575:     }
  576:     const float *w = W_(cat_name(pfx, "merge_layer.0.weight"));
  577:     const float *b = W_(cat_name(pfx, "merge_layer.0.bias"));
  578:     /* nn.InstanceNorm1d(4, affine=True): no running stats exported -> compute
  579:        per-sample-per-channel stats over T (eps=1e-5, the PyTorch default).
  580:        Normalize h in place, then feed it straight into merge_layer.1. */
  581:     instance_norm1d(&h, w, b, B, 4, Tt, 1e-5f);
  582:     /* merge_layer.1 是 4->dim 的 1x1 卷积（逐点、无 pad、无 stride），
  583:      * 所以可以按时间分块、直接把结果算进 y，省掉一整块 [B,dim,Tt]。
  584:      * 每块的取样范围恰好是 [t0,t1) 自己，块与块之间没有任何重叠，
  585:      * 数值与整段调用逐位一致（这是 blocks.c 里既有的分块套路）。
  586:      * 块宽沿用 JX_CHUNK，0 表示整段。 */
  587:     const float *mw = W_(cat_name(pfx, "merge_layer.1.weight"));
  588:     const float *mb = W_(cat_name(pfx, "merge_layer.1.bias"));
  589:     int WW = chunk_width();
  590:     y->shape[0] = B; y->shape[1] = dim; y->shape[2] = Tt; y->len = B*dim*Tt;
  591:     if (WW <= 0 || Tt <= WW)
  592:       {
  593:         T merged = t_alloc(3, (int[]){B, dim, 0});
  594:         conv1d(mw, mb, &h, &merged, 4, dim, 1, 1, 0, 1, Tt);
  595:         /* y = x + merged * x   （r81：二分并行） */
  596:         { jx_ew_t ew; ew.a = x->d; ew.b = merged.d; ew.y = y->d;
  597:           ew.n = B * dim * Tt; ew.mode = 0;
  598:           jx_pf_run_min(ew.n, jx_ew_range, &ew, 2); }
  599:         t_free(&merged);
  600:       }
  601:     else
  602:       {
  603:         for (int bi = 0; bi < B; bi++)
  604:           for (int t0 = 0; t0 < Tt; t0 += WW)
  605:             {
  606:               int t1 = t0 + WW; if (t1 > Tt) { t1 = Tt; }
  607:               int w = t1 - t0;
  608:               T hc = t_alloc(3, (int[]){1, 4, w});
  609:               T mc = t_alloc(3, (int[]){1, dim, w});
  610:               if (hc.d == NULL || mc.d == NULL)
  611:                 {
  612:                   t_free(&hc); t_free(&mc);
  613:                   jx_conv_skip++;
  614:                   printf("[ENH] 分块缓冲分配失败，跳过本次 enhance\n");
  615:                   t_free(&h);
  616:                   return;
  617:                 }
  618:               for (int c = 0; c < 4; c++)
  619:                   memcpy(&hc.d[(size_t)c * w], &h.d[((size_t)bi * 4 + c) * Tt + t0], (size_t)w * sizeof(float));
  620:               conv1d(mw, mb, &hc, &mc, 4, dim, 1, 1, 0, 1, w);
  621:               for (int c = 0; c < dim; c++)
  622:                 {
  623:                   const float *xp = &x->d[((size_t)bi * dim + c) * Tt + t0];
  624:                   float       *yp = &y->d[((size_t)bi * dim + c) * Tt + t0];
  625:                   const float *mp = &mc.d[(size_t)c * w];
  626:                   for (int t = 0; t < w; t++) { yp[t] = xp[t] + mp[t] * xp[t]; }
  627:                 }
  628:               t_free(&hc); t_free(&mc);
  629:             }
  630:       }
  631:     t_free(&h);
  632:     JXP_END(JP_ENHANCE);
  633: }
  634: 
  635: /* ============================ LegacyUnit (modules.LegacyUnit) ============================ */
  636: /* 本体：Snake -> Conv(k=7,p=3*dil) -> Snake -> Conv(k=1)。
  637:  * 时间感受野 = 3*dil（dil<=9 -> 27），其余逐点。分块入口见文末 legacy_unit_add()。 */
  638: static void legacy_unit_core(const T *x, T *y, const char *pfx, int dil) {
  639:     /* LegacyUnit(dim): Snake -> Conv(k=7,p=3*dil) -> Snake -> Conv(k=1) ; residual add inside caller.
  640:        dilation comes from ResidualLegacyUnit(dilation=1/3/9); padding = (k-1)*dil//2 = 3*dil. */
  641:     int B = x->shape[0], C = x->shape[1], Tt = x->shape[2];
  642:     /* 2026-09-14 第三十三轮：原来是 t_copy + snake1d 两趟整张量往返，
  643:      * 合成一趟 snake1d_copy（数值逐位相同）。 */
  644:     T s0 = t_alloc(3, (int[]){B, C, Tt});
  645:     snake1d_copy(&s0, x, W_(cat_name(pfx, "block.0.alpha")));
  646:     /* 2026-09-13 第九轮：这里原来有两次纯搬运，合计每调用 4 个张量往返
  647:      * （T=16032 时约 4MB，实测 ~90ms/次）：
  648:      *   1) conv1d_d 写进 c1 后再 t_copy 到 s1 —— conv1d_d 已经设好
  649:      *      shape[0..2]/len，snake1d 直接吃 c1 就行，复制毫无必要；
  650:      *   2) 末层 conv1d 写进 c2 后再逐元素抄进 y —— 直接让 conv1d 写 y
  651:      *      即可（y->len 恰好等于 need，不会触发 realloc）。
  652:      * 两者都不改任何数值。 */
  653:     T c1 = t_alloc(3, (int[]){B, C, 0});
  654:     /* 第三十三轮：block.2 的 snake 折进 conv1d_d 的 epilogue（省掉一趟整张量往返）。 */
  655:     conv1d_d_snake(W_(cat_name(pfx, "block.1.weight")), W_(cat_name(pfx, "block.1.bias")),
  656:                    &s0, &c1, C, C, 7, 1, 3 * dil, 1, Tt, dil,
  657:                    W_(cat_name(pfx, "block.2.alpha")));
  658:     conv1d(W_(cat_name(pfx, "block.3.weight")), W_(cat_name(pfx, "block.3.bias")), &c1, y, C, C, 1, 1, 0, 1, Tt);
  659:     y->shape[0] = B; y->shape[1] = C; y->shape[2] = Tt; y->len = B*C*Tt;
  660:     t_free(&s0); t_free(&c1);
  661: }
  662: 
  663: void legacy_unit(const T *x, T *y, const char *pfx, int dil) {
  664:     JXP_BEG(JP_LEGACY);
  665:     legacy_unit_core(x, y, pfx, dil);
  666:     JXP_END(JP_LEGACY);
  667: }
  668: 
  669: /* ============================ 时间分块执行 ============================ */
  670: /* 板端 PSRAM 只有 8MB：first_block 在全速率上要同时展开 20/80/81 通道的
  671:  * 张量（3 秒音频约 38MB），conv_unit 也要展开 10*C 通道，整段展开放不下。
  672:  * 这两个算子在时间维度上都是有限感受野（first_block：trend_pool p<=22
  673:  * 加 conv k=7/p=3，共 25 样点；conv_unit：dw_conv k=7/p=3，3 样点），
  674:  * 其余算子逐样点、与时间无关。因此把时间轴切块、每块左右各带一段 halo：
  675:  *   - 中间块只保留 [t0,t1)，halo 区结果丢弃，与整段计算逐位一致；
  676:  *   - 首块/末块的起点/终点就是真实信号边界，各算子 padding 规则不变。
  677:  * 块宽可用环境变量 JX_CHUNK 覆盖，0 表示关闭（主机对照用）。 */
  678: 
  679: #define JX_FB_HALO 64   /* first_block 时间感受野 25，留足余量 */
  680: #define JX_CU_HALO 8    /* conv_unit   时间感受野 3 */
  681: 
  682: static int chunk_width(void)
  683: {
  684:     const char *s = getenv("JX_CHUNK");
  685:     if (s) { int v = atoi(s); return v > 0 ? v : 0; }
  686:     return JX_CHUNK_DEFAULT;
  687: }
  688: 
  689: void first_block(const T *x, T *y) {
  690:     JXP_BEG(JP_FIRSTBLOCK);
  691:     int B = x->shape[0], Tt = x->shape[2]; const int Co = ENC_DIMS[0];
  692:     int W = chunk_width();
  693:     y->ndim = 3; y->shape[0] = B; y->shape[1] = Co; y->shape[2] = Tt;
  694:     y->len = B * Co * Tt;
  695:     if (W <= 0 || Tt <= W) {
  696:         if (first_block_core(x, y) != 0) {
  697:             jx_conv_skip++;
  698:             printf("[FB] first_block_core OOM，跳过\n");
  699:             memset(y->d, 0, (size_t)y->len * sizeof(float));
  700:         }
  701:         JXP_END(JP_FIRSTBLOCK); return;
  702:     }
  703:     for (int bi = 0; bi < B; bi++) {
  704:         for (int t0 = 0; t0 < Tt; t0 += W) {
  705:             int t1 = t0 + W; if (t1 > Tt) t1 = Tt;
  706:             int a = t0 - JX_FB_HALO; if (a < 0) a = 0;
  707:             int e = t1 + JX_FB_HALO; if (e > Tt) e = Tt;
  708:             int w = e - a;
  709:             T xs = t_alloc(3, (int[]){1, 1, w});
  710:             {
  711:                 JXP_BEG(JP_MISC);
  712:                 jx_glue_g_t gg; gg.src = x; gg.dst = xs.d; gg.save = NULL;
  713:                 gg.C = 1; gg.Tt = Tt; gg.bi = bi; gg.a = a; gg.w = w;
  714:                 gg.saved_from = -1; gg.H = 0; gg.split_t = 1;
  715:                 jx_pf_run_min(w, jx_glue_gather, &gg, 64);
  716:                 JXP_END(JP_MISC);
  717:             }
  718:             T ys = t_alloc(3, (int[]){1, Co, w});
  719:             if (first_block_core(&xs, &ys) != 0) { jx_conv_skip++; printf("[FB] chunk OOM t0=%d\n", t0); memset(ys.d, 0, (size_t)ys.len * sizeof(float)); }
  720:             {
  721:                 JXP_BEG(JP_MISC);
  722:                 jx_glue_s_t gs; gs.dst = y->d; gs.src = ys.d; gs.C = Co; gs.Tt = Tt;
  723:                 gs.bi = bi; gs.t0 = t0; gs.n = t1 - t0; gs.off = t0 - a; gs.stride = w; gs.add = 0;
  724:                 jx_pf_run_min(Co, jx_glue_scatter, &gs, 2);
  725:                 JXP_END(JP_MISC);
  726:             }
  727:             t_free(&xs); t_free(&ys);
  728:         }
  729:     }
  730:     JXP_END(JP_FIRSTBLOCK);
  731: }
  732: 
  733: void conv_unit(const T *x, T *y, const char *pfx) {
  734:     JXP_BEG(JP_CONVUNIT);
  735:     int B = x->shape[0], C = x->shape[1], Tt = x->shape[2];
  736:     int W = chunk_width();
  737:     y->ndim = 3; y->shape[0] = B; y->shape[1] = C; y->shape[2] = Tt;
  738:     y->len = B * C * Tt;
  739:     if (W <= 0 || Tt <= W) { conv_unit_core(x, y, pfx); JXP_END(JP_CONVUNIT); return; }
  740:     for (int bi = 0; bi < B; bi++) {
  741:         for (int t0 = 0; t0 < Tt; t0 += W) {
  742:             int t1 = t0 + W; if (t1 > Tt) t1 = Tt;
  743:             int a = t0 - JX_CU_HALO; if (a < 0) a = 0;
  744:             int e = t1 + JX_CU_HALO; if (e > Tt) e = Tt;
  745:             int w = e - a;
  746:             T xs = t_alloc(3, (int[]){1, C, w});
  747:             {
  748:                 JXP_BEG(JP_MISC);
  749:                 jx_glue_g_t gg; gg.src = x; gg.dst = xs.d; gg.save = NULL;
  750:                 gg.C = C; gg.Tt = Tt; gg.bi = bi; gg.a = a; gg.w = w;
  751:                 gg.saved_from = -1; gg.H = 0; gg.split_t = 0;
  752:                 jx_pf_run_min(C, jx_glue_gather, &gg, 2);
