 3669: /****************************************************************************
 3670:  * memhint：内部 RAM / PSRAM 分配探针
 3671:  *
 3672:  * 背景：ESP32-S3 上 PSRAM 与内部 RAM 挂在同一个堆里
 3673:  * （CONFIG_ESP32S3_SPIRAM_COMMON_HEAP），malloc 有可能返回 PSRAM 指针。
 3674:  * 而 Wi-Fi 硬件/ROM 访问不了 PSRAM：一旦 Wi-Fi 库拿到 PSRAM，轻则
 3675:  * 管理帧发不出去（关联/认证失败），重则把 .bss 打坏直接崩机。
 3676:  * 本命令用来量化「内部 RAM 还剩多少块」，判断 Wi-Fi 分配够不够。
 3677:  ****************************************************************************/
 3678: 
 3679: static int jx_ptr_is_psram(const void *p)
 3680: {
 3681:   uintptr_t a = (uintptr_t)p;
 3682:   return (a >= 0x3c000000u && a < 0x3e000000u);
 3683: }
 3684: 
 3685: static int jx_ptr_is_iram(const void *p)
 3686: {
 3687:   uintptr_t a = (uintptr_t)p;
 3688:   return (a >= 0x3fc88000u && a < 0x3fd00000u);
 3689: }
