 3691: static int jx_cmd_memhint(void)
 3692: {
 3693:   static const int sizes[] = { 64, 256, 1024, 4096, 16384 };
 3694:   enum { MAXK = 64 };
 3695:   void *keep[MAXK];
 3696:   struct mallinfo mi0 = mallinfo();
 3697:   int i;
 3698: 
 3699:   printf("=== 内部 RAM / PSRAM 分配探针 ===\n");
 3700:   printf("  堆总览: 空闲=%u 最大空闲块=%u （内部 + PSRAM 合计）\n",
 3701:          (unsigned)mi0.fordblks, (unsigned)mi0.mxordblk);
 3702: 
 3703:   for (int s = 0; s < (int)(sizeof(sizes) / sizeof(sizes[0])); s++)
 3704:     {
 3705:       int n = 0, nin = 0, nps = 0;
 3706:       int size = sizes[s];
 3707: 
 3708:       for (n = 0; n < MAXK; n++)
 3709:         {
 3710:           void *p = malloc((size_t)size);
 3711: 
 3712:           if (p == NULL)
 3713:             {
 3714:               break;
 3715:             }
 3716: 
 3717:           keep[n] = p;
 3718:           if (jx_ptr_is_psram(p))       { nps++; }
 3719:           else if (jx_ptr_is_iram(p))   { nin++; }
 3720:         }
 3721: 
 3722:       printf("  %6d B x %2d: 内部 %2d 块 (%7d B) | PSRAM %2d 块 (%8d B)%s\n",
 3723:              size, n, nin, nin * size, nps, nps * size,
 3724:              (n < MAXK) ? "  [堆耗尽]" : "");
 3725: 
 3726:       for (i = 0; i < n; i++) { free(keep[i]); }
 3727:     }
 3728: 
 3729:   {
 3730:     struct mallinfo mi1 = mallinfo();
 3731:     printf("  释放后: 空闲=%u 最大空闲块=%u\n",
 3732:            (unsigned)mi1.fordblks, (unsigned)mi1.mxordblk);
 3733:   }
 3734: 
 3735:   return 0;
 3736: }
