@@
 static int jx_cmd_stream(int argc, char *argv[])
@@
   return (rc == 0) ? 0 : 1;
 }
+
+/****************************************************************************
+ * streamplay：录制一小段 PCM，然后逐 24ms 包处理并立即播放。
+ * 这是“边处理边播放”的听感验证入口，不做网络传输。
+ ****************************************************************************/
+static int jx_cmd_streamplay(int argc, char *argv[])
+{
+  int secs = (argc >= 3) ? atoi(argv[2]) : 2;
+  struct jx_rec_ctx ctx;
+  struct jx_stream_s *st;
+  int16_t *out = NULL;
+  uint8_t *wav = NULL;
+  int npkt, rc = 0;
+
+  if (secs < 1) { secs = 1; }
+  if (secs > 3) { secs = 3; }
+
+  if (ai_voice_init() != 0)
+    {
+      printf("[ERR] ai_voice_init 失败\n");
+      return 1;
+    }
+  jx_mic_gain_apply();
+
+  ctx.cap = secs * JX_PCM_RATE;
+  ctx.n = 0;
+  ctx.buf = (int16_t *)malloc(sizeof(int16_t) * (size_t)ctx.cap);
+  if (ctx.buf == NULL)
+    {
+      printf("[ERR] 录音缓冲分配失败\n");
+      return 1;
+    }
+
+  printf("=== streamplay：%d 秒录音，逐包处理并立即播放 ===\n", secs);
+  printf("  提示音后开始说，解码完一包就立刻播这一包。\n");
+  for (int i = 0; i < 3; i++)
+    {
+      ai_voice_play_tone(1046, 120);
+      usleep(150 * 1000);
+    }
+  usleep(350 * 1000);
+  ai_voice_play_tone(1568, 400);
+  usleep(250 * 1000);
+
+  printf("  录音中 ...\n");
+  (void)ai_voice_stream_record(jx_rec_cb, &ctx, secs, 0);
+  printf("  录音结束: %d 样本 (%.2f s)\n", ctx.n,
+         (double)ctx.n / JX_PCM_RATE);
+
+  npkt = ctx.n / JX_PKT_SAMPLES;
+  st = jx_stream_open(512);
+  if (st == NULL)
+    {
+      printf("[ERR] 流状态分配失败\n");
+      free(ctx.buf);
+      return 1;
+    }
+
+  out = (int16_t *)malloc(sizeof(int16_t) * JX_PKT_SAMPLES);
+  wav = (uint8_t *)malloc(44u + sizeof(int16_t) * JX_PKT_SAMPLES);
+  if (out == NULL || wav == NULL)
+    {
+      printf("[ERR] 播放缓冲分配失败\n");
+      rc = 1;
+      goto done;
+    }
+
+  for (int k = 0; k < npkt; k++)
+    {
+      int64_t tok[JX_PKT_FRAMES];
+      float pcm[JX_PKT_SAMPLES];
+      double t0 = jx_now_ms();
+      int wav_size;
+
+      rc = jx_stream_feed(st, &ctx.buf[(size_t)k * JX_PKT_SAMPLES], tok, pcm);
+      if (rc != 0)
+        {
+          printf("[ERR] 第 %d 包处理失败 rc=%d\n", k, rc);
+          break;
+        }
+      for (int i = 0; i < JX_PKT_SAMPLES; i++)
+        {
+          float v = pcm[i];
+          if (v > 1.0f) { v = 1.0f; }
+          if (v < -1.0f) { v = -1.0f; }
+          out[i] = jx_round_s16((double)v);
+        }
+      wav_size = ai_voice_wav_encode(wav, out,
+                                     (uint32_t)JX_PKT_SAMPLES * 2u);
+      if (k == 0)
+        {
+          printf("  开始逐包播放（首包计算 %.0f ms）...\n", jx_now_ms() - t0);
+        }
+      (void)ai_voice_play(wav, (size_t)wav_size);
+    }
+
+  printf("  共处理 %d 包\n", jx_stream_pkts(st));
+
+done:
+  jx_stream_close(st);
+  free(out); free(wav); free(ctx.buf);
+  return rc == 0 ? 0 : 1;
+}
*** End Patch
'@; & $codex --codex-run-as-apply-patch $patch", "workdir": "E:\jixuncodec_prj", "yield_time_ms": 10000, "max_output_tokens": 20000}

