+    }
+  if (nframes > st->win)
+    {
+      return -2;
+    }
+
+  memmove(st->buf, &st->buf[n_smp],
+          sizeof(int16_t) * (size_t)(st->cap - n_smp));
+  memcpy(&st->buf[st->cap - n_smp], pkt,
+         sizeof(int16_t) * (size_t)n_smp);
+
