+    t_free(&endec);
+    if (dec.d == NULL) { t_free(&dec); return -11; }
+    st->t_decnn += jx_now_ms() - t_decnn0;
+
+    off = dec.len - st->halo - n_smp;
+    if (off < 0) { off = 0; }
+    for (int i = 0; i < n_smp; i++)
