static int ui_hit_button(int x, int y)
{
  int i;
  int bx;

  if (x < BTN_X0 || y < BTN_Y || y >= BTN_Y + BTN_H)
    {
      return -1;
    }

  i = (x - BTN_X0) / (BTN_W + BTN_GAP);
  if (i < 0 || i >= NBTN || i >= NPAGE)
    {
