static void draw_top(void)
{
  int x = 10;
  char buf[16];
  time_t t;
  struct tm tmv;

  fill_rect(0, 0, UI_W, TOP_H, C_TOPBG);
  fill_rect(0, TOP_H - 1, UI_W, 1, C_LINE);

  /* 菱形 logo（用两个三角拼，避免依赖字库里的符号） */
  fill_rect(x + 3, 6, 4, 2, C_CY);
  fill_rect(x + 2, 8, 6, 2, C_CY);
  fill_rect(x + 3, 10, 4, 2, C_CY);
  fill_rect(x + 1, 12, 8, 2, C_CY);
  x += 12;

  text1(x, 4, "极讯 AI CODEC", C_CY, C_TOPBG);
  text1(x + 14 * B->gw, 4, "openvela·S3", C_DIM, C_TOPBG);

  /* 右侧：链路点 + RSSI + 时钟 */
  {
    int rx = UI_W - 8;

    t = time(NULL);
    localtime_r(&t, &tmv);
    snprintf(buf, sizeof(buf), "%02d:%02d", tmv.tm_hour, tmv.tm_min);
    rx -= 5 * B->gw;
    text1(rx, 4, buf, C_DIM, C_TOPBG);

    for (int i = 0; i < B->rssi; i++)
      {
        fill_rect(rx - 8 - i * 4, 14 - i * 2, 3, 2 + i * 2, C_OK);
      }

    rx -= 38;
    text1(rx, 4, B->link_up ? "链路通" : "链路断", C_DIM, C_TOPBG);

    fill_rect(rx - 12, 9, 6, 6, B->link_up ? C_OK : C_BAD);
  }
}

