/* ---- idx 文件格式: int32 B, int32 Tt, int32 origT, 然后 int64[B*Tt] 小端 ---- */
#define IDX_HDR_WORDS 3
static int write_idx(const char *path, int B, int Tt, int origT, const int64_t *idx) {
    FILE *f = fopen(path, "wb");
    if (!f) { fprintf(stderr, "[err] cannot open %s for write\n", path); return -1; }
    int hdr[IDX_HDR_WORDS] = { B, Tt, origT };
