/****************************************************************************
 * CRC32（按位实现，够快也够小；载荷最大几 KB）
 ****************************************************************************/

static uint32_t jx_crc32(const uint8_t *p, int n)
{
  uint32_t crc = 0xffffffffu;
  int i, b;

  for (i = 0; i < n; i++)
    {
      crc ^= p[i];
      for (b = 0; b < 8; b++)
        {
          crc = (crc >> 1) ^ (0xedb88320u & (uint32_t)(-(int32_t)(crc & 1u)));
        }
    }

  return crc ^ 0xffffffffu;
}

