  if (fd < 0)
    {
      printf("[net] socket 失败: %d\n", errno);
      return -1;
    }

  setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf));

  memset(&me, 0, sizeof(me));
  me.sin_family      = AF_INET;
  me.sin_port        = htons((uint16_t)port);
  me.sin_addr.s_addr = htonl(INADDR_ANY);

