   * 与 ties-away 的差别），相对 1 LSB，远低于 int8 量化噪声。JX_NO_RNDS 可回退。 */
  int r;
  __asm__ ("round.s %0, %1, 0" : "=r"(r) : "f"(v));
  return r;
#else
  unsigned u;
  float h;
  __builtin_memcpy(&u, &v, 4);
  u = 0x3f000000u | (u & 0x80000000u);   /* ±0.5f 的位模式 */
  __builtin_memcpy(&h, &u, 4);
