   24:  * CRC32（按位实现，够快也够小；载荷最大几 KB）
   25:  ****************************************************************************/
   26: 
   27: static uint32_t jx_crc32(const uint8_t *p, int n)
   28: {
   29:   uint32_t crc = 0xffffffffu;
   30:   int i, b;
   31: 
   32:   for (i = 0; i < n; i++)
   33:     {
   34:       crc ^= p[i];
   35:       for (b = 0; b < 8; b++)
   36:         {
   37:           crc = (crc >> 1) ^ (0xedb88320u & (uint32_t)(-(int32_t)(crc & 1u)));
   38:         }
   39:     }
   40: 
   41:   return crc ^ 0xffffffffu;
   42: }
