   48: int jx_net_pack_bits(const int64_t *idx, int ntok, int bits,
   49:                      uint8_t *out, int out_cap)
   50: {
   51:   int bit = 0;
   52:   int i, b;
   53:   int total = ntok * bits;
   54: 
   55:   memset(out, 0, (size_t)out_cap);
   56:   if (total > out_cap * 8)
   57:     {
   58:       total = out_cap * 8;
   59:     }
   60: 
   61:   for (i = 0; i < ntok; i++)
   62:     {
   63:       uint64_t v = (uint64_t)idx[i];
   64: 
   65:       for (b = bits - 1; b >= 0; b--)
   66:         {
   67:           if (bit >= total)
   68:             {
   69:               return bit;
   70:             }
   71: 
   72:           if ((v >> b) & 1u)
   73:             {
   74:               out[bit >> 3] |= (uint8_t)(1u << (7 - (bit & 7)));
   75:             }
   76: 
   77:           bit++;
   78:         }
   79:     }
   80: 
   81:   return bit;
   82: }
   83: 
   84: int jx_net_unpack_bits(const uint8_t *in, int nbits, int bits,
   85:                        int64_t *idx, int max_tok)
   86: {
   87:   int bit = 0;
   88:   int t;
   89: 
   90:   for (t = 0; t < max_tok && bit + bits <= nbits; t++)
   91:     {
   92:       uint64_t v = 0;
   93:       int b;
   94: 
   95:       for (b = 0; b < bits; b++)
   96:         {
   97:           v = (v << 1) | (uint64_t)((in[bit >> 3] >> (7 - (bit & 7))) & 1u);
   98:           bit++;
   99:         }
  100: 
  101:       idx[t] = (int64_t)v;
  102:     }
  103: 
  104:   return t;
  105: }
