  239:     {
  240:       printf("[net] socket 失败: %d\n", errno);
  241:       return -1;
  242:     }
  243: 
  244:   setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &rcvbuf, sizeof(rcvbuf));
  245: 
  246:   memset(&me, 0, sizeof(me));
  247:   me.sin_family      = AF_INET;
